// which Overground line(s) a station name belongs to (by normalised name)
export function overgroundLinesForStation(name) {
  const norm = normaliseStationName(name);
  const out = [];
  for (const [line, stations] of Object.entries(OVERGROUND_LINE_STATIONS)) {
    if (stations.some((s) => normaliseStationName(s) === norm)) out.push(line);
  }
  return out;
}
